SELECT id
FROM certification_question
WHERE catalog_id = #{catalogId}
  AND deleted = 0

    AND subject_id = #{subjectId}

ORDER BY id ASC

SELECT COUNT(*)
FROM certification_question
WHERE catalog_id = #{catalogId}
  AND deleted = 0

    AND subject_id = #{subjectId}

SELECT q.id, q.catalog_id, q.subject_id, q.question_text, q.choice1, q.choice2, q.choice3, q.choice4, q.answer_no, q.explanation, q.created_at, sub.name AS subjectName FROM certification_question q LEFT JOIN subject sub ON sub.id = q.subject_id WHERE q.catalog_id = #{catalogId} AND q.deleted = 0
AND q.subject_id = #{subjectId}
ORDER BY q.id ASC LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*)
FROM certification_question
WHERE catalog_id = #{catalogId}
  AND deleted = 0

    AND subject_id = #{subjectId}

